&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;trackst&amp;nbsp;Markenmetriken&amp;nbsp;(Awareness, Equity, Engagement)&amp;nbsp;sowie&amp;nbsp;Kampagnen-KPIs und&amp;nbsp;nutzt&amp;nbsp;die&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;se&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Daten für eine kontinuierliche Optimierung&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du arbeitest eng mit crossfunktionalen Teams zusammen, um ein konsistentes Markenerlebnis im D2C-Bereich, Pureplay und am Point of Sale &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;zu garantieren&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;TextRun SCXW22428633 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;Du&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;stimmst&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;dich&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;eng&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;mit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;den&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;lokalen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;Commercial-Teams ab, um die&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;Marketingaktivitäten&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;perfekt&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;auf die Markt- und&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;Vertriebsziele&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;auszurichten&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Deine&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Erfahrung&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;&amp;amp; Skills&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:281,&amp;quot;335559739&amp;quot;:281}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;bringst&amp;nbsp;4–6 Jahre&amp;nbsp;fundierte&amp;nbsp;Berufserfahrung&amp;nbsp;als&amp;nbsp;Brand-&amp;nbsp;oder&amp;nbsp;Marketing Manager&amp;nbsp;im&amp;nbsp;FMCG- /&amp;nbsp;Konsumgüterbereich&amp;nbsp;mit.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Gerne aus dem Bereich Food &amp;amp; Beverage&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;hast&amp;nbsp;nachweisbare&amp;nbsp;Erfahrung&amp;nbsp;in der&amp;nbsp;Führung&amp;nbsp;oder&amp;nbsp;Betreuung&amp;nbsp;eine&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;r&amp;nbsp;oder&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;mehrerer&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Marken in&amp;nbsp;der Schweiz mit Umsätzen&amp;nbsp;von&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;mindestens&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;50 Mio&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;. CHF&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;besitzt&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;fundierte Erfahrung&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;in der Steuerung eines&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;D2C-Business&amp;nbsp;sowie in der Steuerung von&amp;nbsp;Omnichannel-Kampagnen (inkl. Mass Media, Influencer Marketing&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Social Media wie TikTok und Meta&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, sowie Point of Sale + Pureplay&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;)&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du zeichnest dich durch eine starke Hands-on-Mentalität, ausgeprägte Fähigkeiten im Projektmanagement und echte Lust auf crossfunktionale Zusammenarbeit aus&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du hast ein strategisches, kreatives und datengetriebenes Mindset und gehst sicher mit digitalen Marketing-Tools um&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du hast verhandlungssichere Deutsch- (Schweizerdeutsch) sowie fließende Französischkenntnisse und nutzt Englisch sicher für unsere interne Kommunikation&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;Warum wir?&amp;nbsp;&lt;/h3&gt;
&lt;p data-start=&quot;258&quot; data-end=&quot;599&quot;&gt;Bei The Quality Group arbeiten über 1.200 Menschen mit einer gemeinsamen Mission: Ernährung neu zu denken - gesünder, smarter und mit echtem Mehrwert für die Community.&lt;br data-start=&quot;434&quot; data-end=&quot;437&quot;&gt;Wir glauben an Teamgeist, Eigenverantwortung und den Mut, Grenzen zu verschieben. Dabei zählt jeder Beitrag, unabhängig vom Standort oder Bereich.&lt;br&gt;Je nachdem, wo du bei uns einsteigst, erwarten dich unterschiedliche Benefits, unter anderem:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Attraktive Mitarbeiterrabatte auf Produkte von ESN &amp;amp; More&lt;/li&gt;
&lt;li&gt;Flexible Arbeitszeiten &amp;amp; Homeoffice-Möglichkeiten&lt;/li&gt;
&lt;li&gt;Zuschüsse zu Mobilität &amp;amp; Fitness (z. B. Wellpass, Deutschlandticket)&lt;/li&gt;
&lt;li&gt;Betriebliche Altersvorsorge&lt;/li&gt;
&lt;li&gt;Workation-Optionen und mehr&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;981&quot; data-end=&quot;1212&quot;&gt;Im Bewerbungsprozess erfährst du, welche Vorteile dich an deinem Standort konkret erwarten und was es heißt, Teil von &lt;strong data-start=&quot;1101&quot; data-end=&quot;1108&quot;&gt;TQG&lt;/strong&gt; zu sein: Ein Unternehmen, das mit Leidenschaft, Qualität und Mut die Zukunft von Ernährung gestaltet.&lt;/p&gt;
&lt;p data-start=&quot;981&quot; data-end=&quot;1212&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;Über uns&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;The Quality Group (TQG) ist ein innovativer Anbieter von Sporternährungsprodukten und vereint seit 2021 die erfolgreichen Marken ESN und More Nutrition. &lt;br&gt;&lt;br&gt;ESN ist seit 2004 deutscher Marktführer für Sporternährung und bietet Produkte wie Proteinpulver, Riegel und Supplements, die auf ambitionierte Fitnessziele ausgerichtet sind. More Nutrition, gegründet 2017, steht für gesunde, zuckerreduzierte Ernährungsprodukte und bietet Lösungen für bewusste Ernährung und Gewichtsmanagement – ohne Verzicht. &lt;br&gt;&lt;br&gt;Die Vision von TQG ist es, Menschen dabei zu unterstützen, die beste Version ihrer selbst zu werden. Mit Leidenschaft und Innovationskraft entwickelt das Unternehmen hochwertige Produkte, die Gesundheit, Leistung und Lebensfreude fördern. Mit einer agilen Unternehmenskultur und spannenden Karrieremöglichkeiten ist TQG nicht nur für Kunden, sondern auch für Mitarbeitende ein starker Partner. &amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;strong&gt;Das sind wir – The Quality Group – nice to meet you! Now it’s your turn!&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Wir freuen uns auf deine Bewerbung! Unabhängig von Geschlecht, Alter, Herkunft oder Identität – bei uns zählt, wer du bist und was du einbringst. Werde Teil unseres Teams und wachse mit uns.&amp;nbsp;&lt;/p&gt;Find Jobs in Switzerland on Arbeitnow

&lt;p&gt;We are looking for passionate technologists to join our Pre-Sales organization to ensure that our growth is grounded and guided by strong technical alignment with our platform and the needs of our customers.&lt;/p&gt;
&lt;p&gt;MongoDB Pre-Sales Solution Architects are responsible for guiding our customers and users to design and build reliable, scalable systems using our data platform. Our team is made up of seasoned technical sales professionals, software architects, entrepreneurs, and developers who take direct responsibility for customer success, including the design of their software, deployment, and operations. You&#39;ll work closely with our sales executives, helping customers solve business problems by leveraging our solutions, playing a key role in winning deals and driving the business forward. You&#39;ll be a trusted advisor to a wide range of users from startups to the world&#39;s largest enterprise IT organizations.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role will be based remotely in Switzerland.&lt;/p&gt;
&lt;h3&gt;As an ideal candidate, you will have:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Ideally 8 to 11 years of related experience in a customer facing role, with 5 to 7 years of experience in pre-sales with enterprise software&lt;/li&gt;
&lt;li&gt;Minimum of 3 years experience with modern scripting languages (e.g. Python, Node.js, SQL) and/or popular programming languages (e.g. C/C++, Java, C#) in a professional capacity&lt;/li&gt;
&lt;li&gt;Experience designing with scalable and highly available distributed systems in the cloud and on-prem&lt;/li&gt;
&lt;li&gt;Demonstrated ability to work with customers to review complex architecture of existing applications, providing guidance on how to improve by leveraging technology&lt;/li&gt;
&lt;li&gt;Excellent presentation, communication, and interpersonal skills, with the ability to convey complex technical and business concepts in a clear and compelling manner to technology and business leadership&lt;/li&gt;
&lt;li&gt;Ability to strategize with sales teams and provide recommendations on how to drive a multi-threaded account strategy, aligning other MongoDB and ecosystem resources to move towards a mutually beneficial account plan&lt;/li&gt;
&lt;li&gt;The ability to travel up to 25%&lt;/li&gt;
&lt;li&gt;A Bachelor’s degree or equivalent work experience&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;You may also have:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience selling databases and/or deploying applications with any of the major cloud providers&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with database programming and data models&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience in data engineering or AI/ML projects&lt;/li&gt;
&lt;li&gt;Experience in transforming legacy systems and platforms into modern, scalable, and efficient technology stacks&lt;/li&gt;
&lt;li&gt;Understanding of popular sales methodologies/ frameworks such as MEDDPICC/ Command of the Message&lt;/li&gt;
&lt;li&gt;A MongoDB Certification&lt;/li&gt;
&lt;li&gt;A Cloud Provider Certification&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What you do at MongoDB:&lt;/h3&gt;
&lt;p&gt;In this role, you will work on complex opportunities where analysis of situations or data requires an in-depth evaluation of various factors. You will:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design and Architect: Design scalable and performant applications, systems and infrastructure for large software projects leveraging MongoDB&lt;/li&gt;
&lt;li&gt;Customer Advising and Value Articulation: Guide customers on architecture patterns and optimisation strategies for MongoDB, while clearly communicating its business value to the relevant stakeholders&lt;/li&gt;
&lt;li&gt;Sales Partnership: Collaborate with the sales team to drive account success through account planning, opportunity prioritization/qualification and pipeline generation strategy, while taking ownership of the technical aspects (including but not limited to technical discovery, demos, proof of value, presentations, sizing and documentation)&lt;/li&gt;
&lt;li&gt;Demand Generation: Proactively generate demand within the sales territory through self-driven technical initiatives, participation in events such as industry trade shows and account-based marketing events&lt;/li&gt;
&lt;li&gt;Customer Success: Foster strong customer relationships, build champions and ensure customer success and satisfaction&lt;/li&gt;
&lt;li&gt;Innovation and Improvement: Continuously seek opportunities to innovate and improve MongoDB solutions and processes (e.g. by relaying field feedback to the product team), as well as proactively mentor other Solutions Consulting team members&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Personal Training and Development: Engage in ongoing training and professional development to stay abreast of MongoDB product suite as well as industry trends&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What you will learn:&lt;/h3&gt;
&lt;p&gt;MongoDB Product Suite Mastery:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Core Database Server: Master the fundamentals and advanced features of MongoDB&#39;s core database&lt;/li&gt;
&lt;li&gt;Atlas and Advanced Services: Gain expertise in Atlas (fully managed cloud database service), Atlas Stream Processing, Atlas Data Lake, Atlas Full-Text Search, Atlas Vector Search, and Charts&lt;/li&gt;
&lt;li&gt;Relational Migrator: Learn to migrate from relational databases seamlessly&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Market-Relevant Technologies:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Hyperscaler Ecosystem: Gain expertise in designing complex systems utilizing cloud services on hyperscaler platforms&lt;/li&gt;
&lt;li&gt;Complementary Technologies: Enhance your skills with partner and complementary technologies such as Apache Kafka and Kubernetes&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Modern Architecture Design:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design Patterns and Methodologies: Embrace best practices in microservices, DevOps, cloud, and security&lt;/li&gt;
&lt;li&gt;Cutting Edge RAG and AI Architectures: Help customers on their generative AI journeys and working with industry leading partners in the space&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Sales Techniques and Soft Skills:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Effective Communication: Master presentations, demonstrations, and whiteboarding&lt;/li&gt;
&lt;li&gt;Client Interaction: Develop strategies for discovery and objection handling&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Industry Insights:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Diverse Market Verticals: Gain exposure to a broad spectrum of interesting use cases across various industries&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;About MongoDB&lt;/h3&gt;
&lt;p&gt;MongoDB is built for change, empowering our customers and our people to innovate at the speed of the market. We have redefined the data platform for the AI era, enabling builders to create, transform, and disrupt industries with software. MongoDB’s unified data platform, the most widely available, globally distributed data platform on the market, helps organizations modernize legacy workloads, embrace innovation, and unleash AI. Our cloud-native platform, MongoDB Atlas, is the only globally distributed, multi-cloud data platform and is available across AWS, Google Cloud, and Microsoft Azure.&lt;/p&gt;
&lt;p&gt;With offices worldwide and over 67,000 customers, including AI-native startups and approximately 75% of the Fortune 100, relying on MongoDB for their most important applications, we’re powering the next era of software.&lt;/p&gt;
&lt;p&gt;Our compass at MongoDB is our &lt;a href=&quot;https://www.mongodb.com/company&quot;&gt;Leadership Commitment,&lt;/a&gt; guiding how and why we make decisions, show up for each other, and win. It’s what makes us MongoDB.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;To drive the personal growth and business impact of our employees, we’re committed to developing a supportive and enriching culture for everyone. &lt;a href=&quot;https://www.mongodb.com/company/blog/culture/employee-benefits-that-make-a-difference-at-mongodb&quot;&gt;From employee affinity groups, to fertility assistance and a generous parental leave policy&lt;/a&gt;, we value our employees’ wellbeing and want to support them along every step of their professional and personal journeys.&lt;a href=&quot;https://www.mongodb.com/blog/channel/culture&quot;&gt; Learn more about what it’s like to work at MongoDB&lt;/a&gt;, and help us make an impact on the world!&lt;/p&gt;
&lt;p&gt;MongoDB is committed to providing any necessary accommodations for individuals with disabilities within our application and interview process. To request an accommodation due to a disability, please inform your recruiter.&lt;/p&gt;
&lt;p&gt;MongoDB is an equal opportunities employer.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Req ID: 427004&lt;/em&gt;&lt;/p&gt;Find more English Speaking Jobs in Switzerland on Arbeitnow

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;758&quot; data-local-id=&quot;349f5d1d97ae&quot;&gt;We are seeking a Staff Applied AI Researcher to join a fast-growing team building an agent-native search platform - the web access layer for AI systems.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;912&quot; data-local-id=&quot;52da8de25c65&quot;&gt;You can think of this as Google search, but for AI agents: a system designed for machines, not humans. We are building agentic search, where AI systems actively plan, retrieve, evaluate, and refine information rather than simply returning results. As AI becomes the primary interface to the web, this layer will replace the role of traditional search engines.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;1273&quot; data-local-id=&quot;8ba2f733eb98&quot;&gt;We are designing these systems to search and reason over web data in real time, under strict latency and reliability constraints. This means solving retrieval, ranking and passage extraction under entirely new access patterns and at significant scale, with systems operating over constantly changing, unstructured data and serving tens of thousands of production workloads 24/7.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;1653&quot; data-local-id=&quot;dc8aefa0b2c5&quot;&gt;This role comes with ownership over key parts of our applied AI research direction and system design, with a strong expectation of defining new approaches and shipping measurable impact in production. In the first year, you will own a specific part of the search stack, e.g. ranking or iterative retrieval.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;1961&quot; data-local-id=&quot;3a68defafc73&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;What you&#39;ll work on:&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;b2d49ed7-2072-4623-afb5-0f3e46fb9eff&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1985&quot; data-local-id=&quot;dbde4a36f318&quot;&gt;Designing an agent-native search system that handles everything from low-latency single-hop search to complex deep search tasks requiring iterative planning, querying, refinement and reasoning.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2182&quot; data-local-id=&quot;330562c2b43d&quot;&gt;Training ranking and retrieval models optimized for agent-driven workflows under real world constraints&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2289&quot; data-local-id=&quot;a80b20c7f5e2&quot;&gt;Bringing the latest advances from the research community to our search stack and ship it to production.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;2396&quot; data-local-id=&quot;c5f3d6d01f8e&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Your responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;ca556365-56d6-4b18-a6ab-e96d32aada2a&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2422&quot; data-local-id=&quot;ba12fa15e8c5&quot;&gt;Drive applied research and technical direction across retrieval and ranking systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2509&quot; data-local-id=&quot;0ac01c95d3f6&quot;&gt;Design and evolve multi-stage retrieval architectures (query understanding, rewriting, retrieval, reranking and iterative retrieval)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2645&quot; data-local-id=&quot;bdd93b58a974&quot;&gt;Lead experimentation on modern retrieval approaches (embedding research, sparse and hybrid retrieval, reranking, context compression) and bring them into production&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2813&quot; data-local-id=&quot;5d99bb2639e8&quot;&gt;Develop methods for grounding LLMs in real-time web data at scale, using trust, quality and freshness signals to surface reliable sources&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2954&quot; data-local-id=&quot;5b539cf905a3&quot;&gt;Partner with the evaluation team to define new metrics for agentic systems, where correctness is not reducible to clicks&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3078&quot; data-local-id=&quot;7f6ed1a6999b&quot;&gt;Analyze trade-offs across relevance, latency, and cost, and work closely with engineering to deploy systems that operate at web scale&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3215&quot; data-local-id=&quot;98cbe59fe7ce&quot;&gt;Mentor researchers and engineers and help raise the technical bar of the team&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;3296&quot; data-local-id=&quot;4e7298218846&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Must haves:&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;288927ca-3161-4538-89a9-be6a7978542a&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3311&quot; data-local-id=&quot;3c107fbda2c8&quot;&gt;8+ years of experience in applied AI, ML, or software engineering&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3380&quot; data-local-id=&quot;529c36f68cf3&quot;&gt;Proven track record of shipping ML or AI systems to production at scale&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3455&quot; data-local-id=&quot;a88ee0b3e468&quot;&gt;Deep experience with search, retrieval, ranking or building RAG-based assistants&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3539&quot; data-local-id=&quot;9b58081ace33&quot;&gt;Strong understanding of modern deep learning, especially transformers and embeddings&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
