&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Executive presence:&lt;/strong&gt; Ability to establish credibility and build lasting relationships with C-level stakeholders.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Consultative selling:&lt;/strong&gt; Strong discovery, listening, questioning, and value-articulation skills.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Strategic thinking:&lt;/strong&gt; Ability to translate customer business objectives into actionable account and opportunity strategies.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Sales discipline:&lt;/strong&gt; Strong pipeline management, forecasting accuracy, prioritization, and execution.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Entrepreneurial mindset:&lt;/strong&gt; Self-motivated, proactive, resilient, and comfortable operating in a dynamic, growth-oriented environment.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Collaboration:&lt;/strong&gt; Ability to mobilize cross-functional teams and leverage internal and external resources effectively.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Technical curiosity:&lt;/strong&gt; Willingness to develop a strong understanding of cybersecurity, PKI, digital identities, certificate automation, and digital trust technologies.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
