&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working with data-led or platform products&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Understanding of AI, GenAI, or agentic AI concepts and their product applications&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
